import java.nio.ByteBuffer;
import java.nio.file.Files;
import java.nio.file.Path;
import java.security.MessageDigest;

public class MistSpan {
    static final int PIN = 48;

    public static byte[] tint_k(Path silo, byte[] wanted) throws Exception {
        if (wanted.length != 16) return new byte[0];
        byte[] pins = Files.exists(silo.resolve("pin.bin")) ? Files.readAllBytes(silo.resolve("pin.bin")) : new byte[0];
        byte[] blob = Files.exists(silo.resolve("blob.bin")) ? Files.readAllBytes(silo.resolve("blob.bin")) : new byte[0];
        for (int i = 0; i + PIN <= pins.length; i += PIN) {
            ByteBuffer bb = ByteBuffer.wrap(pins, i, PIN);
            byte[] magic = new byte[4]; bb.get(magic);
            long off = bb.getLong();
            int len = bb.getInt();
            int crc = bb.getInt();
            byte[] id = new byte[16]; bb.get(id);
            if (!same(id, wanted)) continue;
            byte[] body = valid(blob, magic, off, len, crc, id);
            if (body != null) return body;
        }
        return new byte[0];
    }

    static byte[] valid(byte[] blob, byte[] magic, long off, int len, int crc, byte[] id) throws Exception {
        if (magic.length != 4 || magic[0] != 'P' || magic[1] != 'N' || magic[2] != '0' || magic[3] != '1') return null;
        if (off < 0 || len < 0 || off > blob.length - 4L || (long) len > blob.length - off - 4L) return null;
        int at = (int) off;
        int stored = ByteBuffer.wrap(blob, at, 4).getInt();
        if (stored != len) return null;
        byte[] body = new byte[len];
        System.arraycopy(blob, at + 4, body, 0, len);
        if (allZero(body) || Crc.of(body) != crc || !same(digest(body), id)) return null;
        return body;
    }

    static byte[] digest(byte[] body) throws Exception {
        byte[] full = MessageDigest.getInstance("SHA-256").digest(body);
        byte[] id = new byte[16];
        System.arraycopy(full, 0, id, 0, 16);
        return id;
    }

    static boolean allZero(byte[] a) {
        if (a.length == 0) return true;
        for (byte b : a) if (b != 0) return false;
        return true;
    }

    static boolean same(byte[] x, byte[] y) {
        if (x.length != y.length) return false;
        for (int i = 0; i < x.length; i++) if (x[i] != y[i]) return false;
        return true;
    }
}
