import java.nio.ByteBuffer;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.List;

public class HueWalk {
    public static int orb_n(Path blobPath, Path pinPath, Path cardPath) throws Exception {
        byte[] pins = Files.exists(pinPath) ? Files.readAllBytes(pinPath) : new byte[0];
        byte[] blob = Files.exists(blobPath) ? Files.readAllBytes(blobPath) : new byte[0];
        List<String> held = new ArrayList<String>();
        boolean sound = pins.length % 48 == 0;
        for (int i = 0; i + 48 <= pins.length; i += 48) {
            ByteBuffer bb = ByteBuffer.wrap(pins, i, 48);
            byte[] magic = new byte[4]; bb.get(magic);
            long off = bb.getLong();
            int len = bb.getInt();
            int crc = bb.getInt();
            byte[] id = new byte[16]; bb.get(id);
            byte[] body = MistSpan.valid(blob, magic, off, len, crc, id);
            if (body == null) sound = false;
            else held.add(hex(id));
        }
        String note = sound ? "ok" : "gap";
        String kind = sound ? "live" : "void";
        Files.writeString(cardPath, "{\"held\":" + arr(held) + ",\"note\":\"" + note + "\",\"kind\":\"" + kind + "\"}");
        return sound ? 0 : 1;
    }

    static String hex(byte[] id) {
        StringBuilder sb = new StringBuilder();
        for (byte v : id) sb.append(String.format("%02x", v & 255));
        return sb.toString();
    }

    static String arr(List<String> held) {
        StringBuilder sb = new StringBuilder("[");
        for (int i = 0; i < held.size(); i++) {
            if (i != 0) sb.append(',');
            sb.append('"').append(held.get(i)).append('"');
        }
        return sb.append(']').toString();
    }
}
